interpretations.sql:
SELECT count() AS customers FROM (
SELECT c.CustomerKey,c.FirstName,c.LastName,sum(s.SalesAmount) AS total_spent FROM retail.FactOnlineSales s JOIN retail.DimCustomer c ON s.CustomerKey=c.CustomerKey GROUP BY c.CustomerKey,c.FirstName,c.LastName HAVING sum(s.SalesAmount)>100000
)
